    'mcp_title' => 'AI Agents (MCP)',
    'mcp_note' => 'Connect Claude Code, Codex, ChatGPT, and other AI agents to the CRM.',
    'mcp_why' => '<strong>Why:</strong> MCP allows AI agents to read and manage your feladatok, projektek, clients, and chats through a unified protocol — with the same access jogosultságok as the web UI.',
    'mcp_intro' => 'TropaTT includes a built-in MCP (Model Context Protocol) server — the same protocol understood by Claude Code, Codex, ChatGPT, and other compatible AI agents.',
    'mcp_item1' => '<strong>620 MCP tools + 6 resources</strong> — feladatok, projektek, clients, contacts, chats, naptár, elemzés, tudás base.',
    'mcp_item2' => '<strong>Same adatok and rules</strong> — every request goes through REST API and RBAC checks, just like the web interface.',
    'mcp_item3' => '<strong>Security</strong> — sensitive adatok (tokens, password hashes, API keys) is filtered; writes require appropriate jogosultságok.',
    'mcp_item4' => '<strong>Endpoint:</strong> POST /api/index.php?route=api/v1/mcp, authentication via Bearer token.',
