    'usage_title' => 'Usage Examples',
    'usage_note' => 'Concrete scenarios for different szerepek and industries.',
    'usage_why' => '<strong>Why:</strong> these examples show how TropaTT is used in real workflows — from incoming request to befejezett feladat.',
