    'usage_step1' => '<strong>Capture</strong> — idea, client request, problem, or incoming lead.',
    'usage_step2' => '<strong>Analysis</strong> — on your own or with AI: scope, risks, feasibility, approach.',
    'usage_step3' => '<strong>Structure</strong> — into projektek, feladatok, subtasks, checklists, assignees, deadlines.',
    'usage_step4' => '<strong>Coordination</strong> — via chat, megjegyzések, @mentions, értesítések.',
    'usage_step5' => '<strong>Execution</strong> — feladat lists, Kanban, My Day, My hét.',
    'usage_step6' => '<strong>Tracking</strong> — Gantt, dashboards, elemzés, load, risk signals.',
    'usage_step7' => '<strong>Automation</strong> — workflow rules, SLA, webhooks, approval chains.',
    'usage_examples_heading' => 'Concrete examples',
    'usage_ex1' => '<strong>Freelancer:</strong> client request → AI analyzes → feladat plan → My Day → execution → client chat → done.',
